import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BrModalSize, GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { QrCodeService } from '../../../services/qr-code.service';

@Component({
  selector: 'modal-gerar-qrcode',
  templateUrl: './modal-gerar-qrcode.component.html',
  styleUrl: './modal-gerar-qrcode.component.scss',
  standalone: true,
  providers: [BsModalService], // aqui é necessário fornecer o serviço - por quê?
  imports: [
    CommonModule,
    GovBrModalModule
  ]
})
export class ModalGerarQrcodeComponent implements OnInit {
  imageUrl?: string;

  resizeable = true;
  disabled = false;
  closeButton = true;
  size: BrModalSize = 'sm';

  xxx?: any;
  detalhes?: any;
  tipoAliquota: any;
  unidadeMedida: any;
  output?: any;
  tributo?: number;
  blob?: Blob;
  // 0 - cbs
  // 1 - ibs estadual
  // 2 - ibs municipal
  // 3 - is

  constructor(
    public bsModalService: BsModalService,
    public bsModalRef: BsModalRef,
    private readonly qrCodeService: QrCodeService
  ) { }

  ngOnInit(): void {
    // O blob é passado via initialState do modal e injetado como propriedade direta
    const blob = (this as any).blob;
    if (blob) {
      this.imageUrl = URL.createObjectURL(blob);
    }
  }

  baixar() {
    if (this.imageUrl) {
      this.qrCodeService.salvarQrCode(this.blob, 'teste.png');
    }
  }

  fechar() {
    this.bsModalRef.hide();
  }

}
