import { Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { DispositivoService } from '../../../services/dispositivo.service';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalService, ModalOptions } from 'ngx-bootstrap/modal';
import { ModalDetalhesComponent } from '../modal-detalhes/modal-detalhes.component';
import { DadosCalculadoraService } from '../../../services/dados-calculadora.service';
import { RelatorioService } from '../../../services/relatorio.service';
import { ModalGeradorValidadorXmlComponent } from '../modal-gerador-validador-xml/modal-gerador-validador-xml.component';

@Component({
  selector: 'simulador-calculo-resultado',
  templateUrl: './simulador-calculo-resultado.component.html',
  styleUrl: './simulador-calculo-resultado.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    TooltipModule,
    GovBrModalModule
  ]
})
export class SimuladorCalculoResultadoComponent implements OnInit {

  @Input() dados!: any;
  @Input() tipoAliquota!: string;
  @Input() unidadeMedida!: string;
  @Input() mostrarNcm!: boolean;

  private readonly subscriptions: Subscription = new Subscription();

  dispositivo: string = '';

  output!: any;
  input!: any;
  total!: any;
  isGerandoPdf: boolean = false;

  constructor(
    private readonly dispositivoService: DispositivoService,
    private readonly bsModalService: BsModalService,
    private readonly relatorioService: RelatorioService,
    public dadosCalculadoraService: DadosCalculadoraService
  ) { }

  ngOnInit(): void {
    this.input = this.dadosCalculadoraService.input;
    this.output = this.dadosCalculadoraService.output.objetos[0].tribCalc;
    this.total = this.dadosCalculadoraService.output.total.tribCalc;
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  toNumber(x: string | number): number {
    let num: number = Number(x);
    if (isNaN(num)) {
      console.error("Erro na conversão para número");
      return 0;
    }
    return num;
  }

  // ============ MÉTODO PARA GERAR PDF ============

  async baixarPdf(): Promise<void> {
    if (this.isGerandoPdf) return;

    this.isGerandoPdf = true;
    this.relatorioService.estaGerandoPdf = true;

    try {
      await this.relatorioService.gerarRelatorio();
    } catch (error) {
      console.error('Erro ao gerar PDF:', error);
    } finally {
      this.isGerandoPdf = false;
      this.relatorioService.estaGerandoPdf = false;
    }
  }

  // ============ MÉTODOS DO MODAL ============

  mostrarDetalhes(tributo: number) {
    const modalOptions: ModalOptions = {
      class: 'modal-lg',
      backdrop: true,
      ignoreBackdropClick: false,
      animated: true,
      initialState: {
        output: this.output,
        tributo: tributo
      }
    }
    this.bsModalService.show(ModalDetalhesComponent, modalOptions);
  }

  mostrarValidarXml(tributo: string) {
    const modalOptions: ModalOptions = {
      class: 'modal-xl',
      backdrop: true,
      ignoreBackdropClick: false,
      animated: true,
      initialState: {}
    }
    this.bsModalService.show(ModalGeradorValidadorXmlComponent, modalOptions);
  }

  gerarXml() {
    this.mostrarValidarXml('validar');
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
      })
    );
  }
}
